import java.util.*;
import java.io.*;

public class Main {
    static List<Integer> findDuplicates(int[] nums) {
        // Write your solution here
        // Return the values that occur at least twice, each once, in increasing order.
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) nums[i] = Integer.parseInt(st.nextToken());
        List<Integer> res = findDuplicates(nums);
        if (res.isEmpty()) {
            System.out.println("NONE");
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.size(); i++) sb.append(res.get(i)).append(i + 1 < res.size() ? " " : "");
        System.out.println(sb);
    }
}

