def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([4, 1, 4, 2, 2, 4, 9]), fmt([5, 6, 7, 8]), fmt([-3, -3, 0, 0, 0]), fmt([1]), fmt([1, 1]), fmt([0, 0]),
             fmt([-1, 1, -1, 1]), fmt([10**9, -10**9, 10**9])]
    for n in (3, 5, 8, 12, 20, 40):
        for hi in (3, 10, 1000):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(-1000, 1000) for _ in range(N)]))
    tests.append(fmt(rng.sample(range(-10**9, 10**9), N)))
    tests.append(fmt([-10**9] * N))
    return tests
